# Stdlibs that ship with Julia at a fixed version but can also be upgraded from the registry
# ("upgradable" stdlibs, e.g. `DelimitedFiles` since Julia 1.9 and `Statistics` since 1.11).
# Pkg resolves these like normal packages, so they are recorded here rather than in
# `STDLIBS_BY_VERSION`, which must stay exactly what Pkg expects to load. Only the first
# release in a set of releases that all ship the same versions is stored.
const UPGRADABLE_STDLIBS_BY_VERSION = decode_stdlibs_by_version(STDLIB_UUIDS, [
    v"1.9.0" => [
        "DelimitedFiles" => (v"1.9.1", ["Mmap"]),
    ],
    v"1.11.0" => [
        "Statistics" => (v"1.11.1", ["LinearAlgebra", "SparseArrays"], ["SparseArrays"]),
    ],
    v"1.12.0" => [
        "Statistics" => v"1.11.2",
    ],
    v"1.13.0" => [
        "Statistics" => (v"1.11.2", ["LinearAlgebra"], ["SparseArrays"]),
    ],
    v"1.14.0" => [
        "Statistics" => v"1.11.5",
    ],
])

# Next, we also embed a list of stdlibs that must _always_ be treated as stdlibs,
# because they cannot be resolved in the registry; they have only ever existed within
# the Julia stdlib source tree, and because of that, trying to resolve them will fail.
